function checkForbiddenWords(e) {
  let t = [],
    o = new Set(),
    a = $("#popup-forbidden-words").val();
  if (a)
    try {
      t = JSON.parse(a).map((e) => e.toLowerCase());
    } catch (e) {
      return (
        console.error("Ошибка парсинга запрещённых слов", e),
        { hasForbidden: !1, words: [] }
      );
    }
  const i = ["tg", "site", "vk", "dzen", "max"];
  function escapeRegExp(e) {
    return e.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
  $(e).each(function () {
    let e = $(this),
      n = e.val() || "",
      r = e.attr("name") || "";
    n.match(/<[^>]+>/g) && o.add("HTML-вставка"),
      i.includes(r) ||
        (function () {
          const e = /(?:^|\s)(https?:\/\/[^\s]+)(?=$|\s)/g;
          let t;
          for (; null !== (t = e.exec(n)); ) o.add(`ссылка – ${t[1]}`);
          n = n.replace(/https?:\/\/[^\s]+/g, "");
        })();
    n = n.replace(/<[^>]+>/g, "");
    for (let e of t) {
      if (e) {
        let r = new RegExp(`(^|\\s)${escapeRegExp(e)}(?=\\s|$)`, "i");
        r.test(n) && o.add(e);
      }
    }
  });
  return { hasForbidden: o.size > 0, words: Array.from(o) };
}
function showForbiddenPopup(e) {
  const t = e.map((e) => `"${e}"`).join(", ");
  $("#forbidden-words-list").text(t), $("#forbidden-popup").fadeIn();
}
function uploadPhoto(e, t) {
  $(".photo__rules-block").text(""),
    $(
      ".photo__item .invalid-feedback, #change-photo-mobile .popup__body .photo__wrapper .invalid-feedback"
    ).remove(),
    $(
      ".photo__item .valid-feedback, #change-photo-mobile .popup__body .photo__wrapper .valid-feedback"
    ).remove();
  const o = new FormData();
  o.append("photo_file", $("#photo_file")[0].files[0]),
    $.ajax({
      type: "POST",
      url: "/actions/cabinet/upload_image.php",
      cache: !1,
      contentType: !1,
      processData: !1,
      data: o,
      dataType: "json",
      success: function (t) {
        t.error
          ? ((window.photoUploaded = !1),
            $(
              ".photo__item, #change-photo-mobile .popup__body .photo__wrapper"
            ).append(`<div class="invalid-feedback">${t.error}</div>`))
          : t.success &&
            ((window.photoUploaded = !0), handlePhotoSuccess(t.success, e));
      },
      error: function () {
        window.photoUploaded = !1;
      },
      complete: function () {
        t();
      },
    });
}
function uploadOnlyPhoto(e) {
  e.prop("disabled", !0).text("Сохранение"),
    $(
      ".photo__item .invalid-feedback, #change-photo-mobile .popup__body .photo__wrapper .invalid-feedback"
    ).remove(),
    $(
      ".photo__item .valid-feedback, #change-photo-mobile .popup__body .photo__wrapper .valid-feedback"
    ).remove();
  const t = $("#photo_file")[0];
  if (!t.files.length)
    return void $(".photo__wrapper").append(
      '<div class="invalid-feedback">Выберите фото для загрузки</div>'
    );
  const o = new FormData();
  o.append("photo_file", t.files[0]),
    $.ajax({
      type: "POST",
      url: "/actions/cabinet/upload_image.php",
      cache: !1,
      contentType: !1,
      processData: !1,
      data: o,
      dataType: "json",
      success: function (t) {
        t.error
          ? $(".photo__wrapper").append(
              `<div class="invalid-feedback">${t.error}</div>`
            )
          : t.success && handlePhotoSuccess(t.success, e);
      },
    });
}
function handlePhotoSuccess(e, t) {
  $(".photo__rules-block").remove(),
    $(".photo__item, #change-photo-mobile .popup__body .photo__wrapper").append(
      '<div class="valid-feedback">Фото успешно сохранено.</div>'
    ),
    $(
      ".cabinet-page .cabinet-content .main-info-block .block1 .item .photo__btn"
    )
      .html("<i></i>Изменить")
      .addClass("refresh"),
    $("#change-photo-mobile .popup__body .photo__btn").html("<i></i>Изменить"),
    $(".photo__image")
      .css("background-image", "url(/uploads/avatars/" + e + ")")
      .addClass("refresh"),
    $(".index-mob__info-block .photo-block.profile-photo-mmenu .photo")
      .length &&
      $(".index-mob__info-block .photo-block.profile-photo-mmenu .photo").css(
        "background-image",
        "url(/uploads/avatars/" + e + ")"
      ),
    t.prop("disabled", !0).text("Сохранено");
}
function digits_int(e) {
  let t = $(e)
    .val()
    .replace(/[^0-9]/g, "");
  (t = t.replace(/\B(?=(\d{3})+(?!\d))/g, "'")), $(e).val(t);
}
