  $(document).ready(function () {

    function applyMobileReadonly() {
      const isMobile = window.innerWidth <= 768;
      $('.room-name-input').prop('readonly', isMobile);
    }
    
    $(document).ready(applyMobileReadonly);
    $(window).on('resize', applyMobileReadonly);

    const $form = $("#gallery-info");
    const $submitBtn = $form.find('button[type="submit"]');
  
    // 1. Мгновенное превью при выборе файла
    $form.on("change", ".gallery-file-input", function () {
      const input = this;
      const file = input.files[0];
      const $item = $(input).closest(".gallery-item");
      const $hiddenInput = $item.find(".existing-photo-input");
  
      if (!file || !file.type.startsWith("image/")) {
        alert("Выбранный файл не является изображением");
        input.value = "";
        return;
      }
  
      const reader = new FileReader();
      reader.onload = function (e) {
        $item.css("background-image", `url('${e.target.result}')`)
             .removeClass("empty")
             .addClass("has-image");
        
        $hiddenInput.val(""); // Стираем имя старого файла, так как загружен новый
        $submitBtn.prop("disabled", false); // Активируем кнопку сохранения
      };
      reader.readAsDataURL(file);
    });
  
    // 2. Клик по кнопке "Удалить"
    $form.on("click", ".delete-btn", function (e) {
      e.preventDefault();
      const $item = $(this).closest(".gallery-item");
      
      $item.css("background-image", "").removeClass("has-image").addClass("empty");
      $item.find(".gallery-file-input").val("");
      $item.find(".existing-photo-input").val("");
  
      $submitBtn.prop("disabled", false);
    });
  
    // 3. Оживление мобильной кнопки "Добавить фотографии"
    $form.on("click", ".gallery-add-photo", function () {
      // Ищем самую первую ячейку с классом .empty
      const $firstEmptyItem = $form.find(".gallery-item.empty").first();
      
      if ($firstEmptyItem.length > 0) {
        // Имитируем клик по её лабелу, чтобы открылся выбор файлов
        /* $firstEmptyItem.find(".upload-btn").click(); */
      } else {
        alert("Все 12 слотов галереи уже заполнены!");
      }
    });
  
    // 4. AJAX сохранение всей галереи
    $form.on("submit", function (e) {
      e.preventDefault();
      
      $submitBtn.prop("disabled", true).text("Сохранение");
      const formData = new FormData(this);
  
      $.ajax({
        type: "POST",
        url: "/actions/cabinet/update_gallery.php",
        data: formData,
        contentType: false,
        processData: false,
        dataType: "json",
        success: function (response) {
          if (response.error) {
            alert(response.error);
            $submitBtn.prop("disabled", false).text("Сохранить информацию");
          } else if (response.success) {
            $submitBtn.text("Сохранено");
            
            setTimeout(function () {
              $submitBtn.prop("disabled", true).text("Сохранить информацию");
            }, 2000);
  
            // Идеальное перестроение сетки на лету (закрываем дыры)
            if (response.gallery) {
              $.each(response.gallery, function(index, filename) {
                const $item = $form.find(`.gallery-item[data-index="${index}"]`);
                const $hiddenInput = $item.find(".existing-photo-input");
                const $fileInput = $item.find(".gallery-file-input");
  
                // Всегда сбрасываем выбранный File, так как он уже улетел на сервер
                $fileInput.val("");
  
                if (filename) {
                  // Нулевой индекс лежит в аватарах, остальные — в gallery
                  const folder = (parseInt(index) === 0) ? 'avatars' : 'gallery';
                  
                  $item.css("background-image", `url('/uploads/${folder}/${filename}')`)
                       .removeClass("empty")
                       .addClass("has-image");
                  $hiddenInput.val(filename);
                } else {
                  // Если картинки для этого слота нет — возвращаем блок в состояние "плюсика"
                  $item.css("background-image", "")
                       .removeClass("has-image")
                       .addClass("empty");
                  $hiddenInput.val("");
                }
              });
            }
          }
        },
        error: function () {
          alert("Ошибка сервера при сохранении галереи");
          $submitBtn.prop("disabled", false).text("Сохранить информацию");
        }
      });
    });
  });

  $(document).ready(function () {
    const $form = $("#rooms-info");
    const $submitBtn = $form.find('button[type="submit"]');
    const $popup = $("#room-mobile-popup");
    const MAX_PHOTOS = 4;
    const MAX_NAME_LENGTH = 35; // п.2: не более 35 символов с пробелами
  
    /* ======================================================================
       СОСТОЯНИЕ "ЕСТЬ НЕСОХРАНЁННЫЕ ИЗМЕНЕНИЯ": блокирует удаление залов,
       пока форма не сохранена (см. прочие разделы кабинета)
    ====================================================================== */
  
    let hasUnsavedChanges = false;
  
    function markDirty() {
      hasUnsavedChanges = true;
      $submitBtn.prop("disabled", false);
    }
  
    function markClean() {
      hasUnsavedChanges = false;
      $submitBtn.prop("disabled", true);
    }
    
    // На случай, если в исходной верстке ещё стоит maxlength="65" — подстраховываемся
    $(".room-name-input").attr("maxlength", MAX_NAME_LENGTH);
  
    /* ======================================================================
       ОБЩИЕ УТИЛИТЫ: инлайн-ошибки под полем (красным), как в разделе акции/сотрудники
    ====================================================================== */
  
    // Ошибку вставляем после .room-input-col (блок-обёртку поля), а не сразу после самого инпута
    function getErrorAnchor($el) {
      const $col = $el.closest(".room-input-col");
      return $col.length ? $col : $el;
    }
  
    function getOrCreateFeedback($el) {
      const $anchor = getErrorAnchor($el);
      let $next = $anchor.next(".invalid-feedback");
      if ($next.length) return $next;
      const $fb = $('<div class="invalid-feedback"></div>');
      $anchor.after($fb);
      return $fb;
    }
  
    function showError($el, message) {
      const $fb = getOrCreateFeedback($el);
      $fb.text(message);
      $fb.css("display", "block");
      $el.addClass("is-invalid");
    }
  
    function clearError($el) {
      const $fb = getErrorAnchor($el).next(".invalid-feedback");
      if ($fb.length) $fb.css("display", "none");
      $el.removeClass("is-invalid");
    }
  
    // Отдельный блок ошибки для сетки фото (п.0) — создаётся сразу после .room-photos-grid
    function showPhotoError($grid, message) {
      let $fb = $grid.next(".invalid-feedback.photo-feedback");
      if (!$fb.length) {
        $fb = $('<div class="invalid-feedback photo-feedback"></div>');
        $grid.after($fb);
      }
      $fb.text(message).css("display", "block");
    }
  
    function clearPhotoError($grid) {
      const $fb = $grid.next(".invalid-feedback.photo-feedback");
      if ($fb.length) $fb.css("display", "none");
    }
  
    /* ======================================================================
       ВАЛИДАЦИЯ ДЛИНЫ НАЗВАНИЯ (п.2): красная подсказка под строкой, лимит 35
    ====================================================================== */
  
    function validateNameLength($input) {
      let val = $input.val() || "";
  
      if (val.length > MAX_NAME_LENGTH) {
        val = val.slice(0, MAX_NAME_LENGTH);
        $input.val(val);
      }
  
      if (val.length >= MAX_NAME_LENGTH) {
        showError($input, "Достигнуто максимальное количество символов");
      } else {
        clearError($input);
      }
    }
  
    /* ======================================================================
       ПРОВЕРКА СТОП-СЛОВ / ССЫЛОК / HTML В НАЗВАНИИ (п.1): попап, не инлайн
       Использует глобальные checkForbiddenWords() и showForbiddenPopup(),
       которые уже определены в общем скрипте (см. другие разделы кабинета).
    ====================================================================== */
  
    function validateRoomNameAgainstForbidden(target) {
      // 1. Логируем в консоль, если функции проверки не найдены
      if (typeof checkForbiddenWords !== "function" || typeof showForbiddenPopup !== "function") {
        console.warn("checkForbiddenWords или showForbiddenPopup не доступны в текущей области видимости!");
        return true; 
      }
    
      // 2. Если передали jQuery-объект ($popupName) — берем его напрямую.
      //    Если передали строку (name) — создаем временный input.
      const $el = (target instanceof $) 
        ? target 
        : $("<input>").attr("name", "room_name").val(target);
    
      const { hasForbidden, words } = checkForbiddenWords($el);
    
      if (hasForbidden) {
        showForbiddenPopup(words);
        return false;
      }
    
      return true;
    }
  
    /* ======================================================================
       ОБЯЗАТЕЛЬНОСТЬ ПОЛЕЙ (п.3): без названия ИЛИ название без фото — не сохраняем
    ====================================================================== */
  
    function validateRoomRequired($nameInput, hasPhotos) {
      const name = ($nameInput.val() || "").trim();
      // Проверяем, вызывается ли валидация для мобильного попапа
      const isPopup = $nameInput.is($popupName) || $nameInput.attr("id") === "popup-room-name";
      let isValid = true;
    
      // 1. Валидация наименования
      if (name === "") {
        const nameErrorText = isPopup ? "Введите наименование зала" : "Укажите наименование";
        showError($nameInput, nameErrorText);
        isValid = false;
      } else {
        clearError($nameInput);
      }
    
      // 2. Валидация фотографий
      if (!hasPhotos) {
        if (isPopup) {
          // Для МОБИЛЬНОГО ПОПАПА: ошибка под сеткой фото $popupPhotos
          showPhotoError($popupPhotos, "Загрузите изображение");
        } else {
          // Для ДЕСКТОПА: как было раньше — ошибка под инпутом
          showError($nameInput, "Загрузите изображение");
        }
        isValid = false;
      } else {
        if (isPopup) {
          clearPhotoError($popupPhotos);
        }
      }
    
      return isValid;
    }
  
    /* ======================================================================
       ДЕСКТОП: превью / удаление фото прямо в сетке зала
    ====================================================================== */
  
    $form.on("change", ".room-photo-file-input", function () {
      const input = this;
      const file = input.files[0];
      const $item = $(input).closest(".room-photo-item");
      const $grid = $item.closest(".room-photos-grid");
      const $hiddenInput = $item.find(".existing-room-photo-input");

      clearPhotoError($grid);
  
      const reader = new FileReader();
      reader.onload = function (e) {
        $item
          .css("background-image", `url('${e.target.result}')`)
          .removeClass("empty")
          .addClass("has-image");
  
        $hiddenInput.val(""); // старое имя файла больше не актуально
        markDirty();
  
        // п.3: если фото загружено, снимаем возможную ошибку "загрузите фото" у названия
        const $nameInput = $item.closest(".room-editor-item").find(".room-name-input");
        if (($nameInput.val() || "").trim() !== "") clearError($nameInput);
      };
      reader.readAsDataURL(file);
    });
  
    // Удаление фото из слота (крестик/корзина)
    $form.on("click", ".room-photos-grid .delete-btn", function (e) {
      e.preventDefault();
      const $item = $(this).closest(".room-photo-item");
      const $grid = $item.closest(".room-photos-grid");
  
      $item.css("background-image", "").removeClass("has-image").addClass("empty");
      $item.find(".room-photo-file-input").val("");
      $item.find(".existing-room-photo-input").val("");
      clearPhotoError($grid);
  
      markDirty();
    });
  
    // Изменение названия зала — живая проверка длины (п.2) + активация кнопки сохранения
    $form.on("input", ".room-name-input", function () {
      validateNameLength($(this));
      markDirty();
    });
  
    /* ======================================================================
       ДЕСКТОП: добавление / удаление зала целиком
    ====================================================================== */
  
    let newRoomCounter = 0;
  
    function buildRoomPhotosGrid(roomKey) {
      let html = "";
      for (let i = 0; i < MAX_PHOTOS; i++) {
        html += `
          <div class="room-photo-item empty" data-photo-index="${i}">
            <div class="room-action-btn delete-btn" title="Удалить фото">
              <img src="/assets/img/cabinet/gallery-delete.svg">
              <img src="/assets/img/cabinet/gallery-delete-hover.svg">
            </div>
            <label class="room-action-btn upload-btn" for="room_${roomKey}_photo_${i}" title="Добавить фото">
              <img src="/assets/img/cabinet/gallery-upload.svg">
              <img src="/assets/img/cabinet/gallery-upload-hover.svg">
            </label>
            <input type="file" name="rooms[${roomKey}][photos][${i}]" id="room_${roomKey}_photo_${i}"
                   class="room-photo-file-input" accept="image/jpeg, image/png" style="display:none;">
            <input type="hidden" name="rooms[${roomKey}][existing_photos][${i}]" class="existing-room-photo-input" value="">
          </div>`;
      }
      return html;
    }
  
    $form.on("click", ".add-room-btn", function (e) {
      e.preventDefault();
  
      // На мобилке — открываем попап добавления, а не рисуем блок сразу в списке
      if (window.innerWidth < 575) {
        openRoomPopup(null);
        return;
      }
  
      const roomKey = "new_" + newRoomCounter++;
      const $list = $("#rooms-editor-list");
  
      const roomHtml = `
        <div class="room-editor-item" data-room-index="${roomKey}">
          <div class="room-name-row">
          <div class="room-input-col">
            <input type="text" name="rooms[${roomKey}][name]" class="room-name-input"
                   placeholder="Наименование зала (не более ${MAX_NAME_LENGTH} символов)" maxlength="${MAX_NAME_LENGTH}" value="">
            <div class="room-mobile-actions">
              <a class="edit-docs-mobile" title="Редактировать"></a>
            </div>
            <div class="room-action-btn room-delete-btn desktop-only-btn" title="Удалить зал">
              <img src="/assets/img/cabinet/delete.svg">
              <img src="/assets/img/cabinet/delete_hover.svg">
              <img src="/assets/img/cabinet/delete-disabled.svg">
            </div>
          </div>
          </div>
          <div class="room-photos-grid">${buildRoomPhotosGrid(roomKey)}</div>
        </div>`;
  
      $list.append(roomHtml);
      markDirty();
    });
  
    // п.8: удаление зала — сразу, без доп.попапа-подтверждения (подтверждается через "Сохранить").
    // Пока есть несохранённые изменения — иконка удаления заблокирована (см. прочие разделы).
    $form.on("click", ".room-delete-btn", function (e) {
      e.preventDefault();
  
      const $btn = $(this);
      if ($btn.hasClass("is-empty-room") || $btn.hasClass("disabled")) return;
  
      $btn.closest(".room-editor-item").remove();
      markDirty();
    });
  
    /* ======================================================================
       МОБИЛЬНЫЙ ПОПАП
    ====================================================================== */
  
    const $popupName = $("#popup-room-name");
    const $popupKey = $("#popup-room-key");
    const $popupPhotos = $("#popup-photos-container");
    const $popupAddPhoto = $popup.find(".mob-add");
    const $popupConfirm = $popup.find(".mob-docs-btn");
    const popupConfirmDefaultText = $popupConfirm.text().trim(); // "Подтвердить" — чтобы вернуть текст после подтверждения
  
    function refreshPopupConfirmState() {
      const nameFilled = $popupName.val().trim().length > 0;
      const photosFilled = $popupPhotos.find(".room-photo-item.has-image").length > 0;
    
      const isDisabled = !nameFilled && !photosFilled;
    
      // Управляем и CSS-классом, и HTML-атрибутом disabled
      $popupConfirm
        .toggleClass("disabled", isDisabled)
        .prop("disabled", isDisabled);
    }
  
    function buildPopupPhotoSlot(roomKey, index, hasImage, bgUrl, hiddenVal) {
      return `
        <div class="room-photo-item ${hasImage ? "has-image" : "empty"}" data-photo-index="${index}"
             ${hasImage ? `style="background-image:url('${bgUrl}')"` : ""}>
          <div class="room-action-btn delete-btn" title="Удалить фото">
            <img src="/assets/img/cabinet/gallery-delete.svg">
            <img src="/assets/img/cabinet/gallery-delete-hover.svg">
          </div>
          <label class="room-action-btn upload-btn" for="popup_room_${roomKey}_photo_${index}" title="Добавить фото">
            <img src="/assets/img/cabinet/gallery-upload.svg">
            <img src="/assets/img/cabinet/gallery-upload-hover.svg">
          </label>
          <input type="file" class="popup-room-photo-input" data-photo-index="${index}"
                 id="popup_room_${roomKey}_photo_${index}" accept="image/jpeg, image/png" style="display:none;">
          <input type="hidden" class="popup-existing-photo-input" data-photo-index="${index}" value="${hiddenVal || ""}">
        </div>`;
    }
  
    // Открыть попап. roomKey === null -> создание нового зала, иначе -> редактирование существующего
    function openRoomPopup(roomKey) {
      $popupName.val("");
      $popupKey.val(roomKey === null ? "" : roomKey);
      $popupPhotos.empty();
      clearError($popupName);
    
      let existingPhotos = [];
    
      if (roomKey !== null) {
        const $item = $(`.room-editor-item[data-room-index="${roomKey}"]`);
        $popupName.val($item.find(".room-name-input").val());
    
        $item.find(".room-photo-item").each(function () {
          const isFilled = $(this).hasClass("has-image");
          existingPhotos.push({
            hasImage: isFilled,
            bg: isFilled ? $(this).css("background-image").replace(/^url\(["']?/, "").replace(/["']?\)$/, "") : "",
            hiddenVal: $(this).find(".existing-room-photo-input").val(),
            // 1. Сохраняем File, если он был выбран в основной форме
            file: $(this).find(".room-photo-file-input")[0]?.files?.[0] || null
          });
        });
      }
    
      const filledCount = existingPhotos.filter((p) => p.hasImage).length;
      const slotsToShow = Math.min(filledCount + 1, MAX_PHOTOS);
      const keyForIds = roomKey === null ? "new" : roomKey;
    
      for (let i = 0; i < slotsToShow; i++) {
        const data = existingPhotos[i] || { hasImage: false, bg: "", hiddenVal: "", file: null };
        
        // Создаем DOM-слот попапа
        const $slot = $(buildPopupPhotoSlot(keyForIds, i, data.hasImage, data.bg, data.hiddenVal));
        
        // 2. Если есть File — переносим его в input попапа
        if (data.file) {
          const $popupFileInput = $slot.find(".popup-room-photo-input")[0];
          if ($popupFileInput) {
            const dt = new DataTransfer();
            dt.items.add(data.file);
            $popupFileInput.files = dt.files;
          }
        }
    
        $popupPhotos.append($slot);
      }
    
      updatePopupAddPhotoVisibility();
      
      // 3. Состояние кнопки актуализируется под заполненность полей/фото
      refreshPopupConfirmState();
    
      $popup.fadeIn(200);
      $("body").addClass("hid");
    }
  
    function closeRoomPopup() {
      $popup.fadeOut(200);
      $("body").removeClass("hid");
    }
  
    // п.4 и п.5: строка "Добавить фотографии" появляется только после первого фото
    // и остаётся видимой, пока не заполнены все 4 слота (а не пропадает при добавлении пустого слота)
    function updatePopupAddPhotoVisibility() {
      const filledCount = $popupPhotos.find(".room-photo-item.has-image").length;
      const totalSlots = $popupPhotos.find(".room-photo-item").length;
      $popupAddPhoto.toggle(totalSlots < MAX_PHOTOS);
    }
  
    // Клик по "Редактировать" на карточке зала (мобилка)
    $form.on("click", ".room-mobile-actions", function (e) {
      e.preventDefault();
      const roomKey = $(this).closest(".room-editor-item").data("room-index");
      openRoomPopup(String(roomKey));
    });
  
    // "+ Добавить фотографии" в попапе — открывает следующий пустой слот
    $popupAddPhoto.on("click", function () {
      const totalSlots = $popupPhotos.find(".room-photo-item").length;
      if (totalSlots >= MAX_PHOTOS) return;
  
      const roomKey = $popupKey.val() || "new";
      $popupPhotos.append(buildPopupPhotoSlot(roomKey, totalSlots, false, "", ""));
      updatePopupAddPhotoVisibility();
    });
  
    // Выбор файла внутри попапа
    $popupPhotos.on("change", ".popup-room-photo-input", function () {
      const file = this.files && this.files[0];
      
      // Если выбор файла был отменен — прерываем выполнение, чтобы не упал FileReader
      if (!file) return;
    
      const $slot = $(this).closest(".room-photo-item");
    
      clearPhotoError($popupPhotos);
    
      const reader = new FileReader();
      reader.onload = function (e) {
        // 1. Сначала добавляем класс .has-image
        $slot
          .css("background-image", `url('${e.target.result}')`)
          .removeClass("empty")
          .addClass("has-image");
    
        $slot.find(".popup-existing-photo-input").val("");
    
        updatePopupAddPhotoVisibility();
    
        refreshPopupConfirmState();
      };
    
      reader.readAsDataURL(file);
    });
  
    // Удаление фото внутри попапа
    $popupPhotos.on("click", ".delete-btn", function (e) {
      e.preventDefault();
      const $slot = $(this).closest(".room-photo-item");
      $slot.css("background-image", "").removeClass("has-image").addClass("empty");
      $slot.find(".popup-room-photo-input").val("");
      $slot.find(".popup-existing-photo-input").val("");
      updatePopupAddPhotoVisibility();
      refreshPopupConfirmState();
    });
  
    // Активность кнопки "Подтвердить" зависит от заполненности названия + живая проверка длины (п.2)
    $popupName.on("input", function () {
      refreshPopupConfirmState();
      validateNameLength($(this));
    });
  
    // Закрытие попапа без сохранения
    $popup.on("click", ".popup__close", function () {
      closeRoomPopup();
    });
  
    // п.6: проверка обязательности полей и стоп-слов/ссылок — здесь, при подтверждении попапа,
    // а не при финальном "Сохранить"
    $popupConfirm.on("click", function () {
      if ($(this).hasClass("disabled")) return;
    
      const name = $popupName.val().trim();
      const hasPhotos = $popupPhotos.find(".room-photo-item.has-image").length > 0;
    
      // 1. Клиентская валидация
      if (!validateRoomRequired($popupName, hasPhotos)) return;
      if (!validateRoomNameAgainstForbidden(name)) return;
    
      clearError($popupName);
      clearPhotoError($popupPhotos);
    
      // 2. Проверяем, есть ли новые выбранные файлы для отправки на проверку в PHP
      const formData = new FormData();
      let hasNewFiles = false;
    
      $popupPhotos.find(".room-photo-item").each(function (i) {
        const fileInput = $(this).find(".popup-room-photo-input")[0];
        if (fileInput && fileInput.files && fileInput.files[0]) {
          formData.append(`photos[${i}]`, fileInput.files[0]);
          hasNewFiles = true;
        }
      });
    
      // Вспомогательная функция переваривания данных из попапа в основной список на странице
      function applyPopupDataAndClose() {
        $popupConfirm.addClass("disabled").text("Подтверждение");
    
        let roomKey = $popupKey.val();
        const $list = $("#rooms-editor-list");
    
        if (!roomKey) {
          roomKey = "new_" + newRoomCounter++;
          $list.append(`
            <div class="room-editor-item" data-room-index="${roomKey}">
              <div class="room-name-row">
                <div class="room-input-col">
                  <input type="text" name="rooms[${roomKey}][name]" class="room-name-input new" maxlength="${MAX_NAME_LENGTH}" value="" readonly>
                  <div class="doc mobile-only">
                    <a onclick="$(this).siblings('input[type=file]').click()">
                    </a>
                </div>
                  <div class="room-mobile-actions"><a class="edit-docs-mobile" title="Редактировать"></a></div>
                  <div class="room-action-btn room-delete-btn desktop-only-btn" title="Удалить зал">
                    <img src="/assets/img/cabinet/delete.svg">
                    <img src="/assets/img/cabinet/delete_hover.svg">
                    <img src="/assets/img/cabinet/delete-disabled.svg">
                  </div>
                </div>
              </div>
              <div class="room-photos-grid">${buildRoomPhotosGrid(roomKey)}</div>
            </div>`);
        }
    
        const $item = $list.find(`.room-editor-item[data-room-index="${roomKey}"]`);
        $item.find(".room-name-input").val(name);
    
        $popupPhotos.find(".room-photo-item").each(function (i) {
          const $popupSlot = $(this);
          const $realSlot = $item.find(`.room-photo-item[data-photo-index="${i}"]`);
          if (!$realSlot.length) return;
    
          const hasImage = $popupSlot.hasClass("has-image");
          const bg = $popupSlot.css("background-image");
          const hiddenVal = $popupSlot.find(".popup-existing-photo-input").val();
    
          if (hasImage) {
            $realSlot.css("background-image", bg).removeClass("empty").addClass("has-image");
          } else {
            $realSlot.css("background-image", "").removeClass("has-image").addClass("empty");
          }
          
          // Записываем имя сгенерированного файла .webp
          $realSlot.find(".existing-room-photo-input").val(hiddenVal || "");
        });
    
        $popupConfirm.text("Подтверждено");
    
        setTimeout(function () {
          closeRoomPopup();
          $popupConfirm.removeClass("disabled").text(popupConfirmDefaultText);
          markDirty();
        }, 600);
      }
    
      // 3. Если НОВЫХ файлов нет — сразу применяем изменения
      if (!hasNewFiles) {
        applyPopupDataAndClose();
        return;
      }
    
      // 4. Если ЕСТЬ новые файлы — отправляем их на серверную проверку load_image_webp
      $popupConfirm.addClass("disabled").text("Подтверждение");
    
      $.ajax({
        url: "/actions/cabinet/upload_image_room.php",
        type: "POST",
        data: formData,
        contentType: false,
        processData: false,
        dataType: "json",
        success: function (res) {
          if (res.error) {
            // Ошибка от load_image_webp (например, файл битый, маленький или не того формата)
            showPhotoError($popupPhotos, res.error);
            $popupConfirm.removeClass("disabled").text(popupConfirmDefaultText);
            return; // Прерываем: попап НЕ закрывается
          }
    
          if (res.success && res.photos) {
            // Фото успешно обработаны и сгенерированы в .webp
            $.each(res.photos, function (slotIndex, webpFileName) {
              const $popupSlot = $popupPhotos.find(`.room-photo-item[data-photo-index="${slotIndex}"]`);
              // Записываем имя готового webp в скрытое поле
              $popupSlot.find(".popup-existing-photo-input").val(webpFileName);
              // Очищаем локальный input file, так как файл уже сохранен на сервере
              $popupSlot.find(".popup-room-photo-input").val("");
            });
    
            // Применяем данные к основной форме на странице и закрываем попап
            applyPopupDataAndClose();
          }
        },
        error: function () {
          showPhotoError($popupPhotos, "Ошибка при проверке файла на сервере.");
          $popupConfirm.removeClass("disabled").text(popupConfirmDefaultText);
        }
      });
    });
  
    /* ======================================================================
       AJAX-СОХРАНЕНИЕ ФОРМЫ
    ====================================================================== */
  
    $form.on("submit", function (e) {
      e.preventDefault();
  
      // п.3 + п.1: финальная проверка каждого реального зала перед отправкой на сервер
      let isValid = true;
      let hasForbiddenViolation = false;
      let $firstInvalid = null;
  
      $form.find(".room-editor-item").not(".is-empty-room").each(function () {
        if (hasForbiddenViolation) return;
  
        const $item = $(this);
        const $nameInput = $item.find(".room-name-input");
        const name = ($nameInput.val() || "").trim();
        const hasPhotos = $item.find(".room-photo-item.has-image").length > 0;
  
        if (!validateRoomRequired($nameInput, hasPhotos)) {
          isValid = false;
          if (!$firstInvalid) $firstInvalid = $nameInput;
          return;
        }
  
        if (!validateRoomNameAgainstForbidden(name)) {
          isValid = false;
          hasForbiddenViolation = true;
          if (!$firstInvalid) $firstInvalid = $nameInput;
        }
      });
  
      if (!isValid) {
        if ($firstInvalid) {
          $("html, body").animate({ scrollTop: $firstInvalid.offset().top - 100 }, 300);
        }
        return;
      }
  
      $submitBtn.prop("disabled", true).text("Сохранение");
      const formData = new FormData(this);
  
      $.ajax({
        type: "POST",
        url: "/actions/cabinet/update_rooms.php",
        data: formData,
        contentType: false,
        processData: false,
        dataType: "json",
        success: function (response) {
          if (response.error) {
            if (response.forbidden_words) {
              showForbiddenPopup(response.forbidden_words);
            } else if (response.room_key !== undefined) {
              const $item = $form.find('.room-editor-item[data-room-index="' + response.room_key + '"]');
              if (response.field === "photo") {
                showPhotoError($item.find(".room-photos-grid"), response.error);
              } else {
                showError($item.find(".room-name-input"), response.error);
              }
              $("html, body").animate({ scrollTop: $item.offset().top - 100 }, 300);
            } else {
              alert(response.error);
            }
            $submitBtn.text("Сохранить информацию");
            markDirty(); // изменения не сохранены — удаление залов остаётся заблокированным
            return;
          }
  
          if (response.success) {
            $submitBtn.text("Сохранено");
            markClean(); // данные сохранены — разблокируем удаление залов сразу
  
            setTimeout(function () {
              $submitBtn.text("Сохранить информацию");
            }, 2000);
          }
        },
        error: function () {
          alert("Ошибка сервера при сохранении залов");
          $submitBtn.text("Сохранить информацию");
          markDirty();
        },
      });
    });
  });

